// DE CHIPS VAN DE WEERGAVE: soort-pil, regelbadge, versie-statuschip, chevron.
//
// Eén begrip, drie verschijningsvormen: het TYPE van een kaart of rij is
// tegelijk zijn woord, zijn kleur en zijn term. Daarom staan ze hier bij
// elkaar en niet verspreid over de kaart-, lijst- en verkenner-componenten:
// dezelfde badge hoort op een regelrij, in een groepskop en in het zijpaneel
// exact hetzelfde te zeggen.
//
// Gedragsbron: kindPill, ruleBadge/ruleKind, statusChip en chevron in de
// bevroren viewer (viewer-bevroren/assets/doc.js); de kleuren komen als CSS-tokens uit
// doc.css mee in `gedeeld.css`.
import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { statusWord } from '../../model/parse.js';
import { tekst, weergave } from '../../stores/weergave.js';
import { TERM_VAN_SLEUTEL } from './kop.jsx';
import './gedeeld.css';

/** De vier kaartsoorten van de leesviewer. `request` is in ODRL-termen een
 *  policy zonder aanbod-/overeenkomst-rol (dus een `set`), maar hij heeft een
 *  eigen sectie en een eigen pil. */
export type Kaartsoort = 'set' | 'request' | 'offer' | 'agreement';

/** Het rijtype van een regel — tegelijk de kleurklasse (doc.css) en de
 *  i18n-sleutel van het badgewoord. `aanbod` en `geerfd` zijn de twee
 *  vouw-rijen (doorwerking resp. odrl:inheritFrom, taak 5). */
export type RegelSoort = 'toestemming' | 'verbod' | 'duty' | 'aanbod' | 'geerfd';

const PIL_KLASSE: Record<Kaartsoort, string> = {
  set: 'set', request: 'set request', offer: 'offer', agreement: 'agreement',
};
const PIL_SLEUTEL: Record<Kaartsoort, string> = {
  set: 'kind.set', request: 'kind.request',
  offer: 'kind.offer', agreement: 'kind.agreement',
};
/** Sleutel -> i18n-key voor het badgewoord (RULE_WORD_KEYS in de viewer). */
export const REGEL_SLEUTEL: Record<RegelSoort, string> = {
  toestemming: 'rule.permission', verbod: 'rule.prohibition',
  duty: 'rule.duty', aanbod: 'rule.offer', geerfd: 'rule.inherited',
};

/** De soort-pil vóór de titel van een kaart. */
export function SoortPil(props: { soort: Kaartsoort }): JSX.Element {
  return (
    <span
      class={'kind-pill ' + PIL_KLASSE[props.soort]}
      data-term={TERM_VAN_SLEUTEL[PIL_SLEUTEL[props.soort]]}
    >{tekst(PIL_SLEUTEL[props.soort])}</span>
  );
}

/** De badge op een regelrij. `label` overschrijft het woord (de vouw-rijen
 *  dragen daar hun eigen telling). */
export function RegelBadge(props: { soort: RegelSoort; label?: string }): JSX.Element {
  return (
    <span
      class={'method ' + props.soort}
      data-term={TERM_VAN_SLEUTEL[REGEL_SLEUTEL[props.soort]]}
    >{props.label ?? tekst(REGEL_SLEUTEL[props.soort])}</span>
  );
}

/** De statuschip van een VERSIE, bedoeld om direct achter de kaarttitel te
 *  staan ("Besluit X [vervallen]"). Over de GELDENDE versie zwijgt hij: dat is
 *  de normale stand en een chip die overal staat zegt niets meer. Neutrale
 *  enum als klasse, het weergavewoord uit de modellaag (B17). */
export function VersieChip(props: { status?: string | null }): JSX.Element {
  const toon = () => !!props.status && props.status !== 'current';
  const woord = () => {
    // Reactieve afhankelijkheid op de taal: statusWord leest de stringtabel
    // van de modellaag, en die is zelf niet reactief.
    void weergave.lang;
    return statusWord(props.status);
  };
  return (
    <Show when={toon()}>
      <span class={'vchip ' + props.status}>{woord()}</span>
    </Show>
  );
}

/** Het uitklap-driehoekje: ALTIJD als laatste element van een kopregel. De
 *  vorm tekent CSS (geen tekstglyph: die verschilt per font). Drie maten,
 *  precies die van de bevroren viewer: klein op een regelrij, groot op een
 *  sectiekop (`chevron('lg')`), standaard op een kaart. */
export function Chevron(props: { klein?: boolean; groot?: boolean }): JSX.Element {
  return (
    <span
      class={'chev' + (props.klein ? ' chev-sm' : '') + (props.groot ? ' chev-lg' : '')}
      aria-hidden="true"
    />
  );
}
