// HET SCROLLANKER: de lezer blijft staan waar hij stond.
//
// Gedragsbron: `captureScrollAnchor`, `settleScrollAnchor` en het paar
// `captureListUi`/`restoreListUi` in de bevroren viewer (viewer-bevroren/assets/doc.js).
// Daar hangt het aan `switchLang` (taalwissel, r.1422-1427) en aan de
// fasewissel van de tweefasige lading.
//
// WAAROM EEN ANKER EN GEEN PIXELGETAL. Bij een taalwissel verandert de tekst
// van lengte — en dus de regelval en de hoogte van alles erboven — waardoor
// dezelfde `window.scrollY` een heel ander stuk pagina toont. Het anker vraagt
// niet "hoe ver was ik", maar "wat stond er bovenin"; dat is wat de lezer terug
// wil zien. De pixelpositie blijft als TERUGVAL staan voor het geval het
// ankerelement er na de herbouw niet meer is.
//
// WAT DE NIEUWE APP AL ZELF DOET, en hier dus NIET in zit: de open-stand van de
// kaarten (die staat in de onthouden open-stand van de kaartenlijst), de
// filterteksten (lokale signalen per sectie) en de open filterpanelen. Dat is
// de rest van `captureListUi`; in Solid overleeft het de herrender vanzelf,
// want het staat niet in de DOM. Alleen de scrollpositie is een eigenschap van
// het VENSTER en overleeft niets.
//
// TWEE WISSELS, ÉÉN MECHANIEK. Beide zijn asynchroon (het model wordt opnieuw
// gebouwd) en beide laten de lijst even leeg, waarna de browser scrollY tot 0
// afknijpt. Daarom wordt het anker VASTGEHOUDEN bij de aanleiding en pas
// LOSGELATEN als het nieuwe model binnen is — niet met een vaste vertraging,
// die op een groot corpus altijd te kort of te lang is.

/** Waar de lezer naar keek: welk element bovenin stond, het hoeveelste
 *  voorkomen van die sleutel het was, en hoe ver het onder de bovenrand hing. */
export interface Anker {
  key: string;
  /** Viewport-relatieve bovenrand op het moment van vastleggen. */
  top: number;
  /** DE HOEVEELSTE knoop met deze sleutel. Eén IRI kan meermaals in het
   *  document staan — een regel die in drie beleidssets hangt rendert drie keer
   *  met dezelfde `data-iri`. Zonder dit nummer sprong het herstel naar het
   *  eerste voorkomen, en dat is een heel ander stuk pagina. */
  nr: number;
  /** Terugval als het ankerelement na de herbouw weg is. */
  scrollY: number;
}

const WORTEL = '#app-hoofd';

/** Herhaald terugzetten, want de weergave vult zich nog: lazy kaart-body's en
 *  bijgeladen details laten de pagina ná de herrender nog groeien, en elke groei
 *  bóven het anker duwt het weer weg. Elke ronde corrigeert het verschil; zodra
 *  er niets meer beweegt is het klaar. */
const SETTLE_RONDES = 6;
const SETTLE_PAUZE_MS = 40;

/** Blijft het anker onverzilverd (de fase-2-lading faalde, het model komt niet),
 *  dan mag het niet eeuwig blijven hangen: na deze tijd wordt het alsnog
 *  teruggezet met wat er dan staat. */
const HANGEND_MAX_MS = 4000;

function wortel(): HTMLElement | null {
  if (typeof document === 'undefined' || !document.querySelector) return null;
  return document.querySelector(WORTEL);
}

/** Alle knopen met deze sleutel, in documentvolgorde — dezelfde zoekroute als
 *  bij het vastleggen, anders klopt het volgnummer niet. */
function knopenMet(root: HTMLElement, key: string): HTMLElement[] {
  return [...root.querySelectorAll<HTMLElement>('[data-iri], [data-open-key]')]
    .filter((n) => n.getAttribute('data-iri') === key
      || n.getAttribute('data-open-key') === key);
}

/** Het bovenste ZICHTBARE element met een eigen sleutel, plus hoe ver het onder
 *  de bovenrand van het venster staat.
 *
 *  Niet het eerste zichtbare element, maar het element waarvan de bovenrand het
 *  DICHTST bij de bovenrand van het venster ligt. Het eerste zichtbare is
 *  altijd de buitenste kaart — die begint honderden pixels hoger dan wat de
 *  lezer werkelijk voor zich heeft, en dan verschuift het beeld alsnog zodra de
 *  inhoud daarbóven van lengte verandert. Een regelrij vlak onder de bovenrand
 *  is een veel scherper anker. */
export function legAnkerVast(): Anker | null {
  const root = wortel();
  if (!root || typeof window === 'undefined') return null;
  const hoog = window.innerHeight || 0;
  const scrollY = typeof window.scrollY === 'number' ? window.scrollY : 0;
  let beste: HTMLElement | null = null;
  let besteTop = 0;
  let besteSleutel = '';
  for (const n of root.querySelectorAll<HTMLElement>('[data-iri], [data-open-key]')) {
    const r = n.getBoundingClientRect();
    if (r.bottom <= 0 || r.top > hoog) continue;
    if (!beste || Math.abs(r.top) < Math.abs(besteTop)) {
      beste = n;
      besteTop = r.top;
      besteSleutel = n.getAttribute('data-iri') || n.getAttribute('data-open-key') || '';
    }
  }
  if (!beste || !besteSleutel) return scrollY ? { key: '', top: 0, nr: 0, scrollY } : null;
  return {
    key: besteSleutel,
    top: besteTop,
    nr: Math.max(0, knopenMet(root, besteSleutel).indexOf(beste)),
    scrollY,
  };
}

/** Zet het anker terug op zijn plek. Levert `true` zodra het element gevonden
 *  én gecorrigeerd is; anders valt de aanroeper terug op de pixelpositie. */
export async function zetAnkerTerug(anker: Anker | null): Promise<boolean> {
  if (!anker || typeof window === 'undefined' || !window.scrollBy) return false;
  const root = wortel();
  let geraakt = false;
  if (root && anker.key) {
    for (let i = 0; i < SETTLE_RONDES; i += 1) {
      // HETZELFDE VOORKOMEN als bij het vastleggen: is er er intussen een bij-
      // of afgekomen, dan is het dichtstbijzijnde nog altijd een betere gok dan
      // het eerste.
      const lijst = knopenMet(root, anker.key);
      const knoop = lijst[Math.min(anker.nr, lijst.length - 1)];
      if (!knoop) break;
      const delta = knoop.getBoundingClientRect().top - anker.top;
      geraakt = true;
      if (Math.abs(delta) < 1) return true;
      window.scrollBy(0, delta);
      await new Promise((r) => setTimeout(r, SETTLE_PAUZE_MS));
    }
  }
  if (geraakt) return true;
  if (anker.scrollY && window.scrollTo) {
    window.scrollTo(0, anker.scrollY);
    return true;
  }
  return false;
}

// --- Het hangende anker -----------------------------------------------------
// Vastleggen gebeurt bij de AANLEIDING (de klik op de taalknop, de fasewissel),
// terugzetten pas als het nieuwe model binnen is. Daartussen zit een herbouw van
// onbekende duur; een vaste vertraging zou op /brp-ap altijd verkeerd zijn.

let hangend: Anker | null = null;
let vervalt: ReturnType<typeof setTimeout> | null = null;

/** Leg vast waar de lezer nu staat, en houd dat vast tot het nieuwe model er
 *  is. Een tweede aanroep vóór het loslaten wint niet van de eerste: de eerste
 *  is de plek van vóór de wissel die nu loopt. */
export function houdAnkerVast(): void {
  if (hangend) return;
  hangend = legAnkerVast();
  if (!hangend) return;
  // Komt het model niet (fase 2 faalde), dan mag het anker niet blijven hangen.
  vervalt = setTimeout(() => { void losAnkerLos(); }, HANGEND_MAX_MS);
}

export function heeftHangendAnker(): boolean {
  return hangend !== null;
}

/** Zet het vastgehouden anker terug (en vergeet het). */
export async function losAnkerLos(): Promise<boolean> {
  const a = hangend;
  hangend = null;
  if (vervalt) { clearTimeout(vervalt); vervalt = null; }
  if (!a) return false;
  return zetAnkerTerug(a);
}

// --- DE LEZERPLEK: een herrender mag de lezer niet verplaatsen ---------------
//
// HET ANKER HIERBOVEN IS VOOR DE TRAGE WISSELS: taalwissel en fasewissel, waar
// het model asynchroon opnieuw gebouwd wordt en de tekst van lengte verandert.
// Daar is "wat stond er bovenin" de juiste vraag en is een pixelgetal
// waardeloos.
//
// DIT HIER IS HET SNELLE GEVAL, en het is een ander probleem. Een klik voegt
// een rij toe; de herrender vervangt een stuk DOM waar op dat moment de FOCUS
// in zit. Chromium scrolt dan in het frame waarin dat element verdwijnt uit
// zichzelf weg — een kaal `scroll`-event, zonder dat de app iets vraagt. Op
// `ghost-scroll` is dat 1581 -> 270 gemeten, met een frameprofiel en met een val
// op álle programmeerbare scrollwegen (lane/taal-dropdown, report §6a); de
// sprong komt aantoonbaar niet uit de app. Daarna zet `focusZonderSprong` hem
// vast: vanaf 270 ligt het nieuwe veld onder het venster, dus lijnt zijn
// `scrollIntoView({block:'nearest'})` het netjes op de onderrand uit en staat de
// lezer 451 px verderop.
//
// WAAROM DIT GENERIEK HANGT EN NIET AAN DE TOEVOEGROUTE. Het is geen
// eigenschap van "een rij toevoegen" maar van "een herrender sloopt het element
// met de focus", en dat kan elke bewerkroute overkomen. De aanhaakplek is
// daarom de INTERACTIE zelf: bij elke pointerdown en bij elke activerende
// toetsaanslag onthouden we waar de lezer staat, en wie daarna focus verplaatst
// mag die plek terugvragen. Eén getal, geen DOM-scan — `legAnkerVast()` loopt
// alle `[data-iri]`-knopen af en dat zijn er op BRP-schaal 1.392; dat kan niet
// bij elke muisklik.
//
// WAAROM EEN RUW PIXELGETAL HIER WÉL MAG: tussen de klik en de focus ligt geen
// modelherbouw en verandert er geen tekstlengte. Alles boven de lezer blijft
// even hoog, dus is zijn oude scrollY exact de plek waar hij hoort te staan —
// gemeten: de knoppen-build, die deze browsersprong niet uitlokt, blijft precies
// op 1581 staan.
const PLEK_GELDIG_MS = 1200;
let plek: { y: number; t: number } | null = null;

function onthoudPlek(): void {
  if (typeof window === 'undefined') return;
  plek = { y: window.scrollY || 0, t: Date.now() };
}

/** Scrolt de lezer ZELF, dan is de nieuwe plek de zijne en valt er niets terug
 *  te draaien. */
function vergeetPlek(): void { plek = null; }

if (typeof document !== 'undefined' && document.addEventListener) {
  document.addEventListener('pointerdown', onthoudPlek, true);
  document.addEventListener('keydown', (e) => {
    const k = (e as KeyboardEvent).key;
    if (k === 'Enter' || k === ' ' || k === 'Spacebar') onthoudPlek();
  }, true);
  document.addEventListener('wheel', vergeetPlek, true);
  document.addEventListener('touchmove', vergeetPlek, true);
}

/** Zet de lezer terug op de plek van vlak vóór deze interactie, als er iets hem
 *  daar buiten de app om heeft weggehaald. Eenmalig: de plek is daarna op.
 *  Levert `true` als er werkelijk iets is teruggedraaid.
 *
 *  DE VOORWAARDE IS SMAL, EN DAT IS GEMETEN. Een kale "zet hem terug waar hij
 *  klikte" is te grof: `ghost-scroll-breed` heeft toevoegroutes die ZELF en
 *  terecht scrollen (pad 3, de doelbinding-snelkoppeling die de sloteditor op de
 *  waarde opent), en die draaide hij mee terug — 485 -> 262 waar hij op 485
 *  hoorde te blijven. De diagnose is preciezer dan dat: de browsersprong komt
 *  alleen als de herrender het element met de FOCUS sloopt, en dan staat
 *  `document.activeElement` op dat moment op `<body>` — niets heeft de focus.
 *  Houdt een echte knoop de focus nog vast, dan is er geen sprong geweest en
 *  hoort een scroll die er dan tóch was bij de route zelf. Die toets is dus
 *  geen filter dat het gedrag afzwakt maar de definitie van het geval. */
export function herstelLezerplek(): boolean {
  const p = plek;
  plek = null;
  if (!p || typeof window === 'undefined' || !window.scrollTo) return false;
  if (Date.now() - p.t > PLEK_GELDIG_MS) return false;
  if (typeof document !== 'undefined') {
    const a = document.activeElement;
    if (a && a !== document.body && a !== document.documentElement) return false;
  }
  const nu = typeof window.scrollY === 'number' ? window.scrollY : 0;
  if (Math.abs(nu - p.y) < 2) return false;
  window.scrollTo(0, p.y);
  return true;
}
