// KOPPEN EN VELDLIJSTEN — het gedeelde vocabulaire van de weergave.
//
// De veldkoppen, sectiekoppen en soort-pillen van deze viewer zijn EIGEN
// woorden (i18n.js): "Afnemer" staat er waar de data odrl:assignee zegt,
// "Regels" boven de odrl:Rules. Die woorden zijn een vertaling, geen definitie.
// De tabel hieronder legt de brug — per i18n-sleutel de ODRL-/DCMI-/PROV-term
// waar de kop voor staat — en elke kop draagt hem als `data-term`.
//
// AFWIJKING VAN DE BEVROREN VIEWER, bewust: daar hangt aan diezelfde term ook
// meteen de UITLEG (descriptionFor over de geladen graaf, getoond als
// tooltip-paneeltje). De graaf staat in deze architectuur achter de
// worker-grens en is voor de UI niet leesbaar; `data-term` houdt de brug open
// zodat de taak die de tooltip herbouwt (dt2, verkenner/uitleg) hem hier
// aanhaakt zonder één component te herschrijven.
import { For, Show } from 'solid-js';
import { Dynamic } from 'solid-js/web';
import type { JSX } from 'solid-js';
import { tekst } from '../../stores/weergave.js';

const ODRL = 'http://www.w3.org/ns/odrl/2/';
const DCT = 'http://purl.org/dc/terms/';
const PROV = 'http://www.w3.org/ns/prov#';
const DPV = 'https://w3id.org/dpv#';
const DCAT = 'http://www.w3.org/ns/dcat#';

/** i18n-sleutel -> de term waar de kop voor staat. Letterlijk overgenomen uit
 *  TERM_OF_KEY in de bevroren viewer; alleen de sleutels die de kaartfamilie
 *  gebruikt staan hier (de rest verhuist mee met zijn eigen componenten). */
export const TERM_VAN_SLEUTEL: Record<string, string> = {
  // Partijen en inhoud van een regel
  'field.assigner': ODRL + 'assigner',
  'field.assignee': ODRL + 'assignee',
  'field.action': ODRL + 'action',
  'field.target': ODRL + 'target',
  'field.purpose': ODRL + 'purpose',
  'field.profile': ODRL + 'profile',
  // Herkomst en vindplaats
  'field.issued': DCT + 'issued',
  'field.reference': DCT + 'identifier',
  'field.legalBasis': DPV + 'hasLegalBasis',
  'field.origin': DCT + 'source',
  'field.derivedFrom': PROV + 'wasDerivedFrom',
  'field.fulfilsOffer': PROV + 'wasDerivedFrom',
  'field.replaces': PROV + 'wasRevisionOf',
  'field.sourceLocation': PROV + 'hadPrimarySource',
  // Sectiekoppen. Hier stond `head.rules` → odrl:Rule, de abstracte bovenklasse
  // achter de kaartbrede kop "Regels"; die kop verviel op 9 sep 2026 met de
  // opsplitsing in drie getypeerde subsecties, en de sleutel is met de
  // dode-sleutels-veeg van 10 sep meegegaan.
  // De drie getypeerde subsecties van de regellijst noemen de EIGENSCHAP waaraan
  // de regels op een kaart hangen — niet de klasse. `head.obligations` is
  // odrl:obligation (op een kaart) en `head.duties` odrl:duty (onder een regel):
  // hetzelfde woord in het Nederlands, twee verschillende eigenschappen.
  'head.obligations': ODRL + 'obligation',
  'head.permissions': ODRL + 'permission',
  'head.prohibitions': ODRL + 'prohibition',
  'head.constraints': ODRL + 'constraint',
  'head.duties': ODRL + 'duty',
  'head.consequences': ODRL + 'consequence',
  'head.accessPoints': DCAT + 'accessURL',
  // Soort-pillen en regelbadges
  'kind.set': ODRL + 'Set',
  'kind.offer': ODRL + 'Offer',
  'kind.agreement': ODRL + 'Agreement',
  'kind.request': ODRL + 'Request',
  'rule.permission': ODRL + 'Permission',
  'rule.prohibition': ODRL + 'Prohibition',
  'rule.duty': ODRL + 'Duty',
  'rule.offer': ODRL + 'Offer',
  // De geërfd-badge staat niet voor een KLASSE maar voor de relatie waarlangs
  // de regels binnenkomen: odrl:inheritFrom (zie TERM_OF_KEY in de viewer).
  'rule.inherited': ODRL + 'inheritFrom',
};

/** Het WOORD van een i18n-sleutel, met de term waar het voor staat. */
export function Term(props: { sleutel: string; vars?: Record<string, unknown> }): JSX.Element {
  return (
    <span class="term" data-term={TERM_VAN_SLEUTEL[props.sleutel]}>
      {tekst(props.sleutel, props.vars)}
    </span>
  );
}

/** Een KOP (h2/h3/h4, sectielabel) die zijn term draagt. `tag` bepaalt het
 *  element: de Regels-kop is sinds verbetering 6 een echte `h3` en geen div. */
export function TermKop(props: {
  tag?: string; sleutel: string; class?: string;
}): JSX.Element {
  return (
    <Dynamic
      component={props.tag || 'div'}
      class={props.class}
      data-term={TERM_VAN_SLEUTEL[props.sleutel]}
    >
      {tekst(props.sleutel)}
    </Dynamic>
  );
}

/** Eén rij van een definitielijst. `sleutel` is de i18n-sleutel van de kop
 *  (of `label` voor een kop die de weergave zelf samenstelt); `ref` is de IRI
 *  van de knoop die de waarde aanwijst — het `data-ref`-contract waarop het
 *  invulling-paneel en de sprongen adresseren. */
export interface KvRij {
  sleutel?: string;
  label?: string;
  waarde: JSX.Element | string | null | undefined;
  ref?: string | null;
  /** De UITLEG bij deze kop, als de rij er een meebrengt (sh:description van
   *  een formulierrij, met de definitie van het pad-predicaat als terugval —
   *  zie model/forms.js). Hij staat als `data-desc` op de `<dt>`, dezelfde
   *  plek waar de slot-chips van een voorwaarde hun uitleg dragen: de tooltip
   *  zelf leest de graaf en woont achter de worker-grens, en de taak die haar
   *  herbouwt haakt op één plek aan. */
  desc?: string | null;
}

function gevuld(r: KvRij): boolean {
  return r.waarde != null && r.waarde !== '';
}

/** De definitielijst van een kaart- of regelbody. Lege rijen vallen weg (zoals
 *  kv() in de bevroren viewer); is er niets over, dan komt er geen `<dl>`. */
export function Kv(props: { rijen: KvRij[]; class?: string }): JSX.Element {
  const zichtbaar = () => props.rijen.filter(gevuld);
  return (
    <Show when={zichtbaar().length}>
      <dl class={props.class ? 'kv ' + props.class : 'kv'}>
        <For each={zichtbaar()}>{(r) => (
          <>
            <dt
              data-term={r.sleutel ? TERM_VAN_SLEUTEL[r.sleutel] : undefined}
              data-desc={r.desc || undefined}
            >
              {r.sleutel ? tekst(r.sleutel) : r.label}
            </dt>
            <dd data-ref={r.ref || undefined}>{r.waarde}</dd>
          </>
        )}</For>
      </dl>
    </Show>
  );
}
